// Minimal PatternLock stub for development
class PatternLock {
    constructor(selector, options) {
        this.options = options || {};
        this.element = document.querySelector(selector);
        this.pattern = [];
        this.setupEvents();
    }
    
    setupEvents() {
        if (this.element) {
            this.element.addEventListener('click', () => {
                // Simulate pattern input for development
                const mockPattern = [1, 2, 5, 4]; // Simple L-shape pattern
                if (this.options.onPattern) {
                    this.options.onPattern(mockPattern);
                }
            });
        }
    }
    
    clear() {
        this.pattern = [];
    }
}

window.PatternLock = PatternLock;